#include "Vtb_ca_live_group_directed.h"
#include <iostream>
static void tick(Vtb_ca_live_group_directed&d){d.clk_i=0;d.eval();d.clk_i=1;d.eval();d.clk_i=0;d.eval();}static void reset(Vtb_ca_live_group_directed&d){d.rst_ni=0;d.state_update_i=0;d.test_done_valid_i=0;d.candidate_valid_i=0;d.candidate_pattern_id_i=0;tick(d);tick(d);d.rst_ni=1;}static void start(Vtb_ca_live_group_directed&d){d.state_update_i=1;d.state_sa_i=0;tick(d);d.state_update_i=0;}
static bool preempt(Vtb_ca_live_group_directed&d,unsigned slot){reset(d);start(d);d.candidate_valid_i=1;d.candidate_pattern_id_i=3;for(unsigned i=0;i<slot;++i)tick(d);const uint64_t prior=d.store_o;d.state_update_i=1;d.test_done_valid_i=1;d.test_done_sa_i=0;d.eval();if(d.store_o!=prior)return false;tick(d);d.state_update_i=0;d.test_done_valid_i=0;d.eval();return d.scan_active_o&&d.scan_slot_o==0&&d.frozen_o==0&&d.store_o==prior;}
static bool bist_before(Vtb_ca_live_group_directed&d){reset(d);start(d);d.test_done_valid_i=1;d.test_done_sa_i=0;d.candidate_valid_i=1;for(int i=0;i<3;++i){tick(d);if(i<2&&d.frozen_o)return false;}d.test_done_valid_i=0;return (d.frozen_o&1)&&!d.ready_o;}
static bool solution_before(Vtb_ca_live_group_directed&d){reset(d);start(d);d.candidate_valid_i=1;for(int i=0;i<3;++i)tick(d);if(d.frozen_o||d.ready_o)return false;d.test_done_valid_i=1;d.test_done_sa_i=0;tick(d);d.test_done_valid_i=0;return (d.frozen_o&1)&&!d.ready_o;}
int main(){Vtb_ca_live_group_directed d;for(unsigned slot=0;slot<3;++slot)if(!preempt(d,slot)){std::cerr<<"PREEMPT_FAIL slot="<<slot<<'\n';return 1;}if(!bist_before(d)||!solution_before(d)){std::cerr<<"BIST_OR_PARTIAL_FAIL\n";return 1;}std::cout<<"CA_LIVE_GROUP_DIRECTED_PASS preemption_configs=1,2,3 same_edge_old_result_suppressed=PASS fault_update_wins=PASS old_candidate_write_suppressed=PASS bist_before=PASS solution_before=PASS partial_scan_finalization=FORBIDDEN_AND_VERIFIED\n";}
